.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; gap: .375rem; min-height: 2.125rem; padding: 0 .625rem 0 .5rem; border: 1px solid transparent; border-radius: var(--radius, .5rem); font: 500 var(--ui-text, clamp(.875rem, .63vw, 1rem))/1.25rem var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); white-space: nowrap; cursor: pointer; transition: background-color 130ms ease, border-color 130ms ease; background: var(--primary, #4166eb); color: var(--primary-foreground, #fff); }
.ds-button-primary:hover { background: var(--primary-hover, #3152ce); }
.ds-button-primary:focus-visible { outline: none; border-color: var(--ring, #4166cf); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #4166cf) 50%, transparent); }
.ds-button-primary:active:not(:disabled) { transform: translateY(1px); }
.ds-button-primary:disabled { pointer-events: none; opacity: .5; }
@media (max-width: 37rem), (pointer: coarse) { .ds-button-primary { min-height: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .ds-button-primary { transition-duration: .01ms; } }

.ds-button-outline { display: inline-flex; align-items: center; justify-content: center; gap: .375rem; min-height: 2.125rem; padding: 0 .625rem 0 .5rem; border: 1px solid transparent; border-radius: var(--radius, .5rem); font: 500 var(--ui-text, clamp(.875rem, .63vw, 1rem))/1.25rem var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); white-space: nowrap; cursor: pointer; transition: background-color 130ms ease, border-color 130ms ease; background: var(--muted, #f3f6fa); border-color: var(--border, #dfe5f0); color: var(--foreground, #10192c); }
.ds-button-outline:hover { background: var(--sidebar-hover, #edf1fa); border-color: var(--input, #8a97af); }
.ds-button-outline:focus-visible { outline: none; border-color: var(--ring, #4166cf); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #4166cf) 50%, transparent); }
.ds-button-outline:active:not(:disabled) { transform: translateY(1px); }
.ds-button-outline:disabled { pointer-events: none; opacity: .5; }
@media (max-width: 37rem), (pointer: coarse) { .ds-button-outline { min-height: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .ds-button-outline { transition-duration: .01ms; } }

.ds-button-ghost { display: inline-flex; align-items: center; justify-content: center; gap: .375rem; min-height: 2.125rem; padding: 0 .625rem; border: 1px solid transparent; border-radius: var(--radius, .5rem); font: 500 var(--ui-text, clamp(.875rem, .63vw, 1rem))/1.25rem var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); white-space: nowrap; cursor: pointer; transition: background-color 130ms ease, border-color 130ms ease; background: transparent; color: var(--foreground, #10192c); }
.ds-button-ghost:hover { background: var(--muted, #f3f6fa); }
.ds-button-ghost:focus-visible { outline: none; border-color: var(--ring, #4166cf); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #4166cf) 50%, transparent); }
.ds-button-ghost:active:not(:disabled) { transform: translateY(1px); }
.ds-button-ghost:disabled { pointer-events: none; opacity: .5; }
@media (max-width: 37rem), (pointer: coarse) { .ds-button-ghost { min-height: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .ds-button-ghost { transition-duration: .01ms; } }

.ds-button-danger { display: inline-flex; align-items: center; justify-content: center; gap: .375rem; min-height: 2.125rem; padding: 0 .625rem; border: 1px solid transparent; border-radius: var(--radius, .5rem); font: 500 var(--ui-text, clamp(.875rem, .63vw, 1rem))/1.25rem var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); white-space: nowrap; cursor: pointer; transition: background-color 130ms ease, border-color 130ms ease; background: color-mix(in oklab, var(--destructive, #a73530) 10%, transparent); color: var(--destructive, #a73530); }
.ds-button-danger:hover { background: color-mix(in oklab, var(--destructive, #a73530) 20%, transparent); }
.ds-button-danger:focus-visible { outline: none; border-color: color-mix(in oklab, var(--destructive, #a73530) 40%, transparent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--destructive, #a73530) 20%, transparent); }
.ds-button-danger:active:not(:disabled) { transform: translateY(1px); }
.ds-button-danger:disabled { pointer-events: none; opacity: .5; }
@media (max-width: 37rem), (pointer: coarse) { .ds-button-danger { min-height: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .ds-button-danger { transition-duration: .01ms; } }

.ds-input-label { display: grid; gap: .5rem; color: var(--foreground, #10192c); font: 650 .875rem/1.375 var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); }
.ds-input { min-width: 0; min-height: 2.125rem; padding: .25rem .625rem; border: 1px solid var(--input, #8a97af); border-radius: var(--radius, .5rem); background: transparent; color: var(--foreground, #10192c); caret-color: var(--primary, #4166eb); font: 400 1rem/1.5 var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); }
.ds-input::placeholder { color: var(--muted-foreground, #54647f); }
.ds-input:focus-visible { outline: none; border-color: var(--ring, #4166cf); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #4166cf) 50%, transparent); }
.ds-input[aria-invalid=true] { border-color: var(--destructive, #a73530); box-shadow: 0 0 0 3px color-mix(in oklab, var(--destructive, #a73530) 20%, transparent); }
.ds-input:disabled { pointer-events: none; opacity: .5; background: color-mix(in oklab, var(--input, #8a97af) 50%, transparent); }
@media (min-width: 48rem) { .ds-input { font-size: .875rem; line-height: 1.25rem; } }
@media (max-width: 37rem), (pointer: coarse) { .ds-input { min-height: 2.75rem; font-size: 1rem; } }

.ds-nav { display: flex; align-items: center; gap: .65rem; height: clamp(2.05rem, 1.58vw, 2.5rem); padding-inline: .75rem .44rem; border-radius: .65rem; color: var(--foreground, #10192c); font: 400 var(--ui-text, clamp(.875rem, .63vw, 1rem))/1.55 var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); text-decoration: none; }
.ds-nav:hover, .ds-nav:active { background: var(--sidebar-hover, #edf1fa); }
.ds-nav[aria-current=page] { color: var(--accent-foreground, #304fc2); background: var(--sidebar-selected, #e2e7ff); font-weight: 650; }
.ds-nav:focus-visible { outline: 2px solid var(--ring, #4166cf); outline-offset: 1px; }
.ds-count { min-width: 1.25rem; margin-inline-start: auto; padding: .12rem .38rem; border-radius: 2rem; background: var(--secondary, #eef2f7); color: var(--muted-foreground, #54647f); font: 500 .73rem/1.4 var(--font-mono, "Cascadia Mono", "SFMono-Regular", Consolas, "Liberation Mono", "Microsoft YaHei UI", monospace); text-align: center; }

.ds-panel { min-width: 0; overflow: hidden; border: 1px solid var(--border, #dfe5f0); border-radius: var(--panel-radius, clamp(.75rem, .6vw, .95rem)); background: var(--card, #fff); color: var(--foreground, #10192c); box-shadow: var(--panel-shadow, 0 1px 2px rgb(22 44 84 / 4%)); font: 400 var(--ui-text, clamp(.875rem, .63vw, 1rem))/1.55 var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); }
.ds-panel > header { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: .55rem; min-height: clamp(3.2rem, 2.8vw, 4.45rem); padding: .75rem var(--panel-pad, clamp(1rem, .82vw, 1.32rem)); border-bottom: 1px solid var(--border, #dfe5f0); }
.ds-panel h2 { margin: 0; font: 500 clamp(.975rem, .71vw, 1.13rem)/1.35 var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); }
.ds-panel-badge { display: inline-flex; align-items: center; justify-content: center; gap: .25rem; min-height: clamp(1.32rem, .97vw, 1.54rem); padding: .125rem clamp(.5rem, .46vw, .75rem); border: 1px solid color-mix(in srgb, currentColor 22%, transparent); border-radius: 2rem; color: var(--success-ink, #276c49); background: var(--success-bg, #eaf4ee); font: 500 var(--ui-caption, clamp(.78rem, .55vw, .88rem))/1rem var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); white-space: nowrap; }
.ds-panel dl { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); margin: var(--panel-pad, clamp(1rem, .82vw, 1.32rem)); border: 1px solid var(--border, #dfe5f0); border-radius: .65rem; background: var(--panel-wash, #fbfcfe); }
.ds-panel dl > div { min-width: 0; padding: clamp(.7rem, .77vw, 1.2rem) clamp(.7rem, .65vw, 1.05rem); }
.ds-panel dl > div + div { border-inline-start: 1px solid var(--border, #dfe5f0); }
.ds-panel dt { color: var(--muted-foreground, #54647f); font-size: var(--ui-caption, clamp(.78rem, .55vw, .88rem)); }
.ds-panel dd { margin: .25rem 0; font: 500 clamp(1.24rem, 1.02vw, 1.65rem)/1.25 var(--font-mono, "Cascadia Mono", "SFMono-Regular", Consolas, "Liberation Mono", "Microsoft YaHei UI", monospace); }

.ds-metric { display: flex; position: relative; flex-direction: column; align-items: flex-start; justify-content: center; gap: .5rem; min-width: 0; min-height: clamp(6.1rem, 4.64vw, 7.4rem); padding: .85rem 2.1rem .85rem var(--panel-pad, clamp(1rem, .82vw, 1.32rem)); border: 1px solid var(--border, #dfe5f0); border-radius: var(--panel-radius, clamp(.75rem, .6vw, .95rem)); background: var(--card, #fff); color: var(--foreground, #10192c); box-shadow: var(--panel-shadow, 0 1px 2px rgb(22 44 84 / 4%)); text-decoration: none; }
.ds-metric:hover { border-color: var(--input, #8a97af); }
.ds-metric:focus-visible { outline: 2px solid var(--ring, #4166cf); outline-offset: 3px; }
.ds-metric-label { display: inline-flex; align-items: center; gap: .38rem; color: var(--muted-foreground, #54647f); font: 400 clamp(.76rem, .54vw, .86rem)/1.55 var(--font-sans, "Segoe UI Variable Text", "Segoe UI", "PingFang SC", "Microsoft YaHei UI", "Noto Sans CJK SC", system-ui, sans-serif); }
.ds-metric-label svg { width: .85rem; height: .85rem; color: var(--primary, #4166eb); }
.ds-metric-reading { display: flex; flex-wrap: wrap; align-items: baseline; gap: .15rem .4rem; font-family: var(--font-mono, "Cascadia Mono", "SFMono-Regular", Consolas, "Liberation Mono", "Microsoft YaHei UI", monospace); line-height: 1.25; font-variant-numeric: tabular-nums; }
.ds-metric-reading strong { font-size: clamp(1.24rem, 1.02vw, 1.65rem); font-weight: 500; letter-spacing: -.025em; }
.ds-metric-reading small { font-size: clamp(.75rem, .56vw, .88rem); color: var(--muted-foreground, #54647f); }
.ds-metric-arrow { display: flex; position: absolute; top: 50%; right: var(--panel-pad, clamp(1rem, .82vw, 1.32rem)); color: var(--input, #8a97af); transform: translateY(-50%); transition: transform 150ms ease-out; }
.ds-metric-arrow svg { width: 1.05rem; height: 1.05rem; }
.ds-metric:hover .ds-metric-arrow { color: var(--primary, #4166eb); transform: translate(.15rem, -50%); }
@media (prefers-reduced-motion: reduce) { .ds-metric-arrow { transition-duration: .01ms; } }

.ds-retention { display: grid; grid-template-columns: minmax(2.8rem, 1fr) auto; align-items: center; gap: .65rem; color: var(--foreground, #10192c); font: 400 var(--ui-text, clamp(.875rem, .63vw, 1rem))/1.55 var(--font-mono, "Cascadia Mono", "SFMono-Regular", Consolas, "Liberation Mono", "Microsoft YaHei UI", monospace); font-variant-numeric: tabular-nums; }
.ds-retention progress { display: block; width: 100%; height: clamp(.38rem, .3vw, .46rem); appearance: none; border: 0; border-radius: 2rem; overflow: hidden; background: var(--secondary, #eef2f7); color: var(--primary, #4166eb); }
.ds-retention progress::-webkit-progress-bar { background: var(--secondary, #eef2f7); border-radius: 2rem; }
.ds-retention progress::-webkit-progress-value { background: var(--primary, #4166eb); border-radius: 2rem; }
.ds-retention progress::-moz-progress-bar { background: var(--primary, #4166eb); border-radius: 2rem; }
